#include <iostream>
#include <string>
#include <regex>
#include <sstream>
#include <algorithm>

int getMaxWordLength(const std::string& s) {
    std::istringstream iss(s);
    std::string token;
    int maxLen = 0;
    while (std::getline(iss, token, '_')) {
        maxLen = std::max(maxLen, static_cast<int>(token.length()));
    }
    return maxLen;
}

std::string stripParentheses(const std::string& s) {
    if (s.length() >= 2) {
        return s.substr(1, s.length() - 2);
    }
    return s;
}

int main() {
    int countLines;
    std::cin >> countLines;
    std::cin.ignore(); // ignore the remaining newline after reading integer
    std::string dataLine;
    std::getline(std::cin, dataLine);

    std::string regexPattern = R"(\([\w_]*\))";
    std::regex pattern(regexPattern);
    std::sregex_iterator iter(dataLine.begin(), dataLine.end(), pattern);
    std::sregex_iterator end;

    int maxWordCount = 0;
    long long insideWords = 0;

    for (; iter != end; ++iter) {
        std::string inside = stripParentheses(iter->str());
        maxWordCount = std::max(maxWordCount, getMaxWordLength(inside));
        std::istringstream iss(inside);
        std::string s;
        while (std::getline(iss, s, '_')) {
            if (!s.empty()) {
                ++insideWords;
            }
        }
    }

    std::cout << maxWordCount << " " << insideWords << std::endl;
    return 0;
}
